template:
% 参数由系统自动注入：\def\kind{1} \def\c{4}
% ===== 视图随类型变化（坐标系前先算好范围）=====
\ifnum\kind=1
  \pgfmathtruncatemacro{\xleft}{-4}
  \pgfmathtruncatemacro{\xright}{4}
  \pgfmathtruncatemacro{\ybottom}{-2}
  \pgfmathtruncatemacro{\ytop}{4}
\else\ifnum\kind=2
  \pgfmathsetmacro{\sq}{sqrt(\c)}
  \pgfmathtruncatemacro{\xleft}{-ceil(\sq+2.2)}
  \pgfmathtruncatemacro{\xright}{-\xleft}
  \pgfmathtruncatemacro{\ybottom}{-2}
  \pgfmathtruncatemacro{\ytop}{ceil(\c+1.5)}
  \pgfmathsetmacro{\xexit}{sqrt(\c+\ytop+0.3)}
  \pgfmathsetmacro{\dhi}{min(\xright,\xexit)}
\else\ifnum\kind=3
  \pgfmathtruncatemacro{\xleft}{-4}
  \pgfmathtruncatemacro{\xright}{5}
  \pgfmathtruncatemacro{\ybottom}{-2}
  \pgfmathtruncatemacro{\ytop}{4}
\else
  \pgfmathtruncatemacro{\xleft}{-3}
  \pgfmathtruncatemacro{\xright}{4}
  \pgfmathtruncatemacro{\ybottom}{-3}
  \pgfmathtruncatemacro{\ytop}{4}
\fi\fi\fi
\pgfmathsetmacro{\figscale}{6.5/max(\xright-\xleft,\ytop-\ybottom)}
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % ===== 坐标系 =====
  \draw[->, thick] (\xleft-0.5,0) -- (\xright+0.6,0) node[right] {$x$};
  \draw[->, thick] (0,\ybottom-0.5) -- (0,\ytop+0.6) node[above] {$y$}; % ===== 类型 1：y=|x| =====
  \ifnum\kind=1
    \draw[thick] (\xleft,-\xleft) -- (0,0) -- (\xright,\xright);
    \node[font=\tiny, anchor=east] at (\xright-0.4,\ytop-0.5) {$y=|x|$};
    \fill (0,0) circle [radius=\dotr pt];
  \else\ifnum\kind=2
    % ===== 类型 2：y=|x²-c|，x 轴下方翻折 =====
    \draw[thick, domain=-\dhi:-\sq, samples=60, smooth] plot (\x, {\x*\x-\c});
    \draw[thick, domain=\sq:\dhi, samples=60, smooth] plot (\x, {\x*\x-\c});
    \draw[thick, domain=-\sq:\sq, samples=80, smooth] plot (\x, {\c-\x*\x});
    \fill (-\sq,0) circle [radius=\dotr pt];
    \fill (\sq,0) circle [radius=\dotr pt];
    \fill (0,\c) circle [radius=\dotr pt];
    \node[above right, font=\tiny] at (0,\c) {$(0,c)$};
    \node[below, font=\tiny] at (\sq,0) {$(\sqrt c,0)$};
    \node[below, font=\tiny] at (-\sq,0) {$(-\sqrt c,0)$};
    \node[font=\tiny, anchor=east] at (\dhi-0.3,\ytop-0.5) {$y=|x^2-c|$};
  \else\ifnum\kind=3
    % ===== 类型 3：阶梯分段（端点实心/空心）=====
    \draw[thick] (\xleft,-1) -- (0,-1);
    \draw[thick] (0,1) -- (2,1);
    \draw[thick] (2,3) -- (\xright,3);
    \fill (0,1) circle [radius=\dotr pt];
    \fill (2,3) circle [radius=\dotr pt];
    \draw[thick, fill=white] (0,-1) circle [radius=\dotr pt];
    \draw[thick, fill=white] (2,1) circle [radius=\dotr pt];
  \else
    % ===== 类型 4：两段折线 y=2x+1 (x≤1)，y=-x+4 (x>1) =====
    \draw[thick] (-2,-3) -- (1,3);
    \pgfmathsetmacro{\yer}{-\xright+4}
    \draw[thick] (1,3) -- (\xright,\yer);
    \fill (1,3) circle [radius=\dotr pt];
    \node[above right, font=\tiny] at (1,3) {$(1,3)$};
  \fi\fi\fi
\end{tikzpicture}
